INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-019', TRUE, '经济管理学院', '2026-09-14', '经济管理学院召开巡察整改监督小组会议本网讯 9月10日下午，经济管理学院巡察整改监督小组会议在经管楼302会议室召开。会', '校内通知', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "本网讯 9月10日下午，经济管理学院巡察整改监督小组会议在经管楼302会议室召开", "quote": "本网讯 9月10日下午，经济管理学院巡察整改监督小组会议在经管楼302会议室召开"}]'::jsonb, '校内通知：经济管理学院召开巡察整改监督小组会议本网讯 9月10日下午，经济管理学院巡察整改', '[{"text": "本网讯 9月10日下午，经济管理学院巡察整改监督小组会议在经管楼302会议室召开", "quote": "本网讯 9月10日下午，经济管理学院巡察整改监督小组会议在经管楼302会议室召开"}]'::jsonb, '本网讯 9月10日下午，经济管理学院巡察整改监督小组会议在经管楼302会议室召开。会议由学院党委副书记、纪委书记周涛主持，巡察整改监督小组全体成员参加会议。 会议集中学习习近平总书记重要文章《坚持落实管党治党政治责任》、中国共产党第二十届中央纪律检查委员会第六次全体会议精神；与会成员分别领学《中共安徽农业大学委员会运用监督执纪第一种形态工作实施细则（试行）》、《安徽农业大学落实二级纪委监督责任实施办法》、《关于建立健全全面从严治党 “四责协同” 机制的实施办法（试行）》、《安徽农业大学纵向科研项目经费管理办法》、《', 'https://jgxy.ahau.edu.cn/info/1101/25346.htm', '经济管理学院 · 工作动态', 'jgxy', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at